package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;
/** Seven public input/output pairs; a row-to-row rule is distinct from a successive-term rule. */
public final class PairedNumberTables {
 private PairedNumberTables(){}
 public static final String FILL="pairedNumberTableFill",RULE="pairedNumberTableDescription";
 public static final List<Catalog.Skill> SKILLS=List.of(new Catalog.Skill(FILL,"두 열 값 표 완성하기",6,1,2,"","pairedTableFill",100,"el_number_pattern","첫째 수와 둘째 수의 관계로 표의 빈칸을 채운다."),new Catalog.Skill(RULE,"두 열 값 표의 규칙 설명하기",6,1,2,"","pairedTableRule",100,FILL,"첫째 수에 무엇을 더하거나 빼면 둘째 수가 되는지 설명한다."));
 public record Givens(int[] first,int[] shown,int delta){}
 public static boolean supports(String id){return FILL.equals(id)||RULE.equals(id);}
 public static boolean describe(Question q){return q!=null&&RULE.equals(q.skillId);}
 public static int ruleIndex(Question q){return describe(q)?0:3;}
 public static int amountIndex(Question q){return ruleIndex(q)+1;}
 public static String instruction(Question q){return describe(q)?"첫째 수에서 둘째 수로 가는 규칙을 설명하세요.":"표의 빈칸 세 개를 채우고 규칙을 설명하세요.";}
 public static Givens read(Question q){if(q==null||!supports(q.skillId)||q.prompt==null)return null;String[] lines=q.prompt.split("\n",-1);if(lines.length!=3||!lines[0].startsWith("첫째 수: ")||!lines[1].startsWith("둘째 수: ")||!lines[2].equals(instruction(q)))return null;String[] xs=lines[0].substring(6).split(Pattern.quote(" | "),-1),ys=lines[1].substring(6).split(Pattern.quote(" | "),-1);if(xs.length!=7||ys.length!=7)return null;int[] x=new int[7],y=new int[7];for(int i=0;i<7;i++){if(!xs[i].matches("[0-9]{1,3}"))return null;x[i]=Integer.parseInt(xs[i]);if(x[i]>100||i>0&&x[i]!=x[0]+i)return null;if(i>=4&&FILL.equals(q.skillId)){if(!ys[i].equals("□"))return null;y[i]=-1;}else{if(!ys[i].matches("[0-9]{1,3}"))return null;y[i]=Integer.parseInt(ys[i]);if(y[i]>100)return null;}}int delta=y[0]-x[0];if(delta==0||Math.abs(delta)>12)return null;for(int i=0;i<7;i++){int expected=x[i]+delta;if(expected<0||expected>100||y[i]>=0&&y[i]!=expected)return null;}return new Givens(x,y,delta);}
 public static Question make(String id,int start,int delta){if(!supports(id)||start<0||start+6>100||delta==0||Math.abs(delta)>12||start+delta<0||start+6+delta>100)throw new IllegalArgumentException("Selected paired table bounds");StringJoiner x=new StringJoiner(" | "),y=new StringJoiner(" | ");for(int i=0;i<7;i++){x.add(""+(start+i));y.add(FILL.equals(id)&&i>=4?"□":""+(start+i+delta));}Question q=new Question(id,"","","","");q.prompt="첫째 수: "+x+"\n둘째 수: "+y+"\n"+instruction(q);if(FILL.equals(id)){q.answers=new String[]{""+(start+4+delta),""+(start+5+delta),""+(start+6+delta),delta>0?"0":"1",""+Math.abs(delta)};q.labels=new String[]{"x = "+(start+4),"x = "+(start+5),"x = "+(start+6),"계산","변화량"};q.kind="pairedTableComposite";}else{q.kind="pairedTableDescription";q.labels=new String[]{"계산","변화량"};q.answers=new String[]{delta>0?"0":"1",""+Math.abs(delta)};}q.stepSupport=false;attach(q);return q;}
 static int count(CurriculumLimits l){int max=l.wholeMaximum(100);if(max<18||max>100)throw new IllegalArgumentException("Selected table maximum");int count=0;for(int d=-12;d<=12;d++)if(d!=0)count+=max-5-Math.abs(d);return count;}
 static Question at(String id,int index,CurriculumLimits l){if(index<0||index>=count(l))throw new IllegalArgumentException("Table index");int max=l.wholeMaximum(100);for(int d=-12;d<=12;d++)if(d!=0){int size=max-5-Math.abs(d);if(index<size)return make(id,Math.max(0,-d)+index,d);index-=size;}throw new IllegalArgumentException();}
 static Question next(Catalog.Skill s,Random r,CurriculumLimits l,Map<String,Integer> recent){return IndexedQuestionSupply.choose(count(l),i->at(s.id,i,l),r,l,recent);}
 static Checker.Result check(Question q,List<String> answers){Givens v=read(q);int op=ruleIndex(q),fields=op+2;if(v==null||answers==null||answers.size()!=fields)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"답 입력 필요");if(!describe(q))for(int i=0;i<3;i++){String input=answers.get(i);if(input==null||!input.matches("[0-9]{1,3}"))return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"수 입력 필요");if(Integer.parseInt(input)!=v.first[i+4]+v.delta)return new Checker.Result(Checker.Status.WRONG_ANSWER,i,"이 표의 값 확인");}if(answers.get(op)==null||!List.of("0","1").contains(answers.get(op)))return new Checker.Result(Checker.Status.INPUT_NEEDED,op,"계산 선택 필요");if(!answers.get(op).equals(v.delta>0?"0":"1"))return new Checker.Result(Checker.Status.WRONG_ANSWER,op,"첫째 수에서 둘째 수로 가는 계산 확인");String amount=answers.get(op+1);if(amount==null||!amount.matches("[0-9]{1,3}"))return new Checker.Result(Checker.Status.INPUT_NEEDED,op+1,"변화량 입력 필요");return Integer.parseInt(amount)==Math.abs(v.delta)?new Checker.Result(Checker.Status.CORRECT,-1,"표와 규칙 확인 완료"):new Checker.Result(Checker.Status.WRONG_ANSWER,op+1,"이 변화량 확인");}
 public static void attach(Question q){Givens v=read(q);if(v==null)return;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="paired-number-table-v1";h.step("표의 첫 번째 첫째 수를 쓰세요.","첫째 수 x = ","",""+v.first[0]);h.step("같은 열의 둘째 수를 쓰세요.","둘째 수 y = ","",""+v.shown[0]);h.step("같은 열에서 둘째 수와 첫째 수의 차이를 구하세요.","변화량 d = y − x = ","",""+v.delta);if(!describe(q)){h.step("다음 열에서도 같은 규칙이 맞는지 확인하세요.",v.first[1]+" + d = ","",""+v.shown[1]);for(int i=4;i<7;i++)h.step("첫째 수에 같은 변화량을 더해 빈칸을 채우세요.",v.first[i]+" + d = ","",""+(v.first[i]+v.delta));}Map<String,String> options=new LinkedHashMap<>();options.put("0","첫째 수에 더하기");options.put("1","첫째 수에서 빼기");h.choice("첫째 수에서 둘째 수로 가는 계산을 고르세요.",options,v.delta>0?"0":"1");h.step("더하거나 뺄 수의 크기를 쓰세요.","변화량의 크기 = ","",""+Math.abs(v.delta));q.studyGuide=h;}
}
